/**
 * @method
 * @name setParam
 * @description set Param 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function(GridID, row, colid) {
    const parentWin = $c.frame.path("../");
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    const vFORM_CD = objDataID.getCellData(row, "FORM_CD");
    const vFORM_VER = objDataID.getCellData(row, "FORM_VER");
    const vFORM_KOR_NM = objDataID.getCellData(row, "FORM_KOR_NM");
    const vFORM_ENG_NM = objDataID.getCellData(row, "FORM_ENG_NM");
    if (typeof(parentWin.txb_FORM_CD) === "object") {
        parentWin.txb_FORM_CD.setValue(vFORM_CD);
    }
    if (typeof(parentWin.txb_FORM_VER) === "object") {
        parentWin.txb_FORM_VER.setValue(vFORM_VER);
    }
    if (typeof(parentWin.txb_FORM_KOR_NM) === "object") {
        parentWin.txb_FORM_KOR_NM.setValue(vFORM_KOR_NM);
    }
    if (typeof(parentWin.txb_FORM_ENG_NM) === "object") {
        parentWin.txb_FORM_ENG_NM.setValue(vFORM_ENG_NM);
    }
};

/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 500;
    frame.Height = 500;
};

/**
 * @method
 * @name txb_FormNm_onkeydown
 * @description txb_FormNm 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FormNm_onkeydown = function() {
    if (window.event.keyCode === "13") {
        fn_Search();
    }
};

/**
 * @method
 * @name dts_DocList_OnLoadError
 * @description dts_DocList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DocList_OnLoadError = async function() {
    await $c.win.alert(dts_DocList);
};

/**
 * @method
 * @name dts_DocList_OnLoadCompleted
 * @description dts_DocList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DocList_OnLoadCompleted = async function(rowcount) {
    if (dts_DocList.errorMsg) {
        await $c.win.alert(dts_DocList.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
};

/**
 * @method
 * @name grd_DocList_OnDblClick
 * @description grd_DocList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_DocList_OnDblClick = async function(row, colid) {
    // fn_SetParam(grd_DocList, row, colid);

    // 부모창에 데이타 셋팅
    frame.opener.txb_FormCd.setValue(dts_DocList.getCellData(row, "FORM_CD"));
    frame.opener.txb_FormNm.setValue(dts_DocList.getCellData(row, "FORM_KOR_NM"));
    await $c.win.closePopup();
};

/**
 * @method
 * @name img_Search_onclick
 * @description img_Search 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = function() {
    fn_Search();
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    // 대분류 콤보에 값 셋팅
    scwin.setCode();

    // 세션값에서 로그인한 사람의 세션값을 읽어와서 사용할 시장구분에 셋팅한다.
    scwin.setMktCode();
    fn_Search();
    // n_resizeToWin();

};
